function tokenize(text) { return (text.normalize(&quot;NFC&quot;).toLowerCase().match(/[\\p{L}\\p{M}\\p{N}]+/gu) || []); }
function sentences(text) { return text.split(/(?&lt;=[।?!])\\s+/).map((s) =&gt; s.trim()).filter(Boolean); }
function chunkDoc(doc, maxChars) {
  const out = []; let cur = [];
  for (const s of sentences(doc.text)) {
    if (cur.length &amp;&amp; (cur.join(&quot; &quot;) + &quot; &quot; + s).length &gt; maxChars) { out.push(cur.join(&quot; &quot;)); cur = [cur[cur.length - 1]]; }
    cur.push(s);
  }
  if (cur.length) out.push(cur.join(&quot; &quot;));
  return out.map((text, i) =&gt; ({ id: doc.id + &quot;#&quot; + (i + 1), doc: doc.id, tenant: doc.tenant, vis: doc.vis, updated: doc.updated, title: doc.title, text }));
}

const ret = DOCS.find((d) =&gt; d.id === &quot;policy-return&quot;);
console.log(&quot;বাক্য:&quot;, sentences(ret.text).length);
const chunks = chunkDoc(ret, 120);
chunks.forEach((c) =&gt; console.log(c.id, &quot;|&quot;, c.text.length, &quot;অক্ষর |&quot;, c.text));

const all = DOCS.flatMap((d) =&gt; chunkDoc(d, 120));
console.log(&quot;মোট chunk:&quot;, all.length, &quot;| নথি:&quot;, DOCS.length);
console.log(&quot;metadata উদাহরণ:&quot;, JSON.stringify({ id: all[0].id, tenant: all[0].tenant, vis: all[0].vis, updated: all[0].updated }));
console.log(&quot;টোকেন:&quot;, JSON.stringify(tokenize(&quot;থ্রি-পিসের সাইজ চার্ট?&quot;)));</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>sentences</code>: “।”, “?” বা “!”-এর পরের ফাঁকায় ভাগ (lookbehind <code>(?&lt;=…)</code>—চিহ্নটি বাক্যের সাথেই থাকে)।</li><li><code>chunkDoc</code>: বাক্য যোগ করতে করতে সীমা পেরোলে chunk বন্ধ, শেষ বাক্যটি নতুন chunk-এর শুরুতে (overlap)।</li><li>প্রতিটি chunk-এ নথির metadata কপি—পরে ফিল্টার ও উৎস-উল্লেখের জন্য।</li><li><code>tokenize</code>: অধ্যায় ৬-এর মতো <code>\\p{L}\\p{M}\\p{N}</code>—বাংলা কার-চিহ্ন ও সংখ্যা শব্দের অংশ।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>অক্ষর-সীমা ব্যবহার করা হয়েছে কারণ আসল tokenizer এখানে নেই; বাস্তবে সীমা সাধারণত token-এ মাপা হয়। একটি বাক্যের overlap সহজতম পদ্ধতি; অনুচ্ছেদ-সীমা, শিরোনাম-সচেতন কাটা বা টেবিলকে আলাদা রাখা—এগুলো আসল নথিতে প্রায়ই দরকার।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>RAG = খোঁজা + উত্তর</li><li>বাক্য-সীমায় কাটুন, overlap রাখুন</li><li>chunk id-তে নথির id</li><li>metadata: tenant, vis, updated, title</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>PDF/HTML পার্সিং</li><li>টেবিল ও ছবি</li><li>শিরোনাম-ভিত্তিক hierarchical chunking</li></ul></div></details>
<details class="wgba-disclose" open><summary>নিজে পরিবর্তন করে দেখুন</summary><div><p>সব নথিকে ৪০, ১২০ ও ৪০০ অক্ষরে chunk করুন এবং মোট chunk-সংখ্যা তুলনা করুন। ৪০০-এ প্রতিটি নথি একটি chunk—এতে কোন প্রশ্নের উত্তর খুঁজতে সুবিধা আর কোনটায় অসুবিধা?</p></div></details>
<section class="wgba-section" id="mistakes"><h2>সাধারণ ভুল</h2><ul><li>বাক্যের মাঝখানে নির্দিষ্ট অক্ষর-সংখ্যায় কাটা</li><li>metadata ছাড়া chunk রাখা</li><li>সব নথির জন্য একই দৈর্ঘ্য মেপে না দেখে ধরে নেওয়া</li><li>সিন্থেটিক নীতিকে আসল নীতি হিসেবে ব্যবহার</li></ul></section>
<section class="wgba-section" id="check"><h2>জ্ঞান যাচাই</h2><p>নিচের 3টি প্রশ্নের উত্তর দিয়ে “জমা দিন” চাপুন। স্কোর সার্ভারে যাচাই হয়; প্রতিটি উত্তরের পর কেন সঠিক বা ভুল তা দেখাবে। লগইন থাকলে ফল আপনার অগ্রগতিতে সংরক্ষিত হয়।</p></section>
<section class="wgba-section" id="recap"><h2>সংক্ষেপে মনে রাখুন</h2><ul><li>chunk = একা পড়ে বোঝা যায় এমন টুকরো</li><li>বাক্য-সীমা + overlap</li><li>metadata পরের সব ধাপের ভিত্তি</li></ul></section>
<section class="wgba-section" id="next"><h2>পরবর্তী পাঠ</h2><p>chunk তৈরি। এবার খোঁজা—প্রথমে শব্দ মিলিয়ে, BM25: <a href="/ai-academy/lesson/keyword-search-bm25/">Keyword Search: BM25</a></p></section>
<section class="wgba-section" id="sources"><h2>সূত্র ও যাচাই</h2><ul><li><a href="https://arxiv.org/abs/2005.11401" rel="noopener">Lewis et al. — Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks (2020)</a></li><li><a href="https://www.unicode.org/charts/PDF/U0980.pdf" rel="noopener">Unicode Standard — Bengali block (U+0980–U+09FF)</a></li></ul><p class="wgba-meta">যাচাইয়ের তারিখ: 2026-10-19; লেখক: Muhibbullah Ansary। এই পাঠের 1টি JavaScript উদাহরণ বিল্ডের সময় সাইটের একই QuickJS রানারে চালানো হয়েছে এবং প্রত্যাশিত আউটপুট মিলেছে; সংখ্যাগত ফলাফল আলাদা assertion দিয়ে (floating-point tolerance সহ) পরীক্ষিত। এই পাঠের ডেটা/উদাহরণ শেখানোর জন্য তৈরি সিন্থেটিক ডেটা—বাস্তব কোনো দোকান বা গ্রাহকের নয়। স্বাধীন বিশেষজ্ঞ রিভিউ এখনও হয়নি; ভুল পেলে যোগাযোগ পাতায় জানান।</p></section>',
