const PRODUCTS = [
  { sku: &quot;SAREE-BLUE&quot;, tenant: &quot;shopA&quot;, name: &quot;নীল সুতি শাড়ি&quot;, price: 1200, stock: 8, updated: &quot;2026-10-15 10:00&quot; },
  { sku: &quot;LAWN-3PC&quot;, tenant: &quot;shopA&quot;, name: &quot;লন থ্রি-পিস&quot;, price: 1850, stock: 0, updated: &quot;2026-10-15 10:00&quot; },
  { sku: &quot;SCARF-RED&quot;, tenant: &quot;shopA&quot;, name: &quot;লাল সুতি ওড়না&quot;, price: null, stock: 5, updated: &quot;2026-10-14 18:30&quot; },
  { sku: &quot;B-SAREE-SILK&quot;, tenant: &quot;shopB&quot;, name: &quot;সিল্ক শাড়ি&quot;, price: 5400, stock: 3, updated: &quot;2026-10-15 09:00&quot; },
];
const user = { tenant: &quot;shopA&quot;, role: &quot;customer&quot; };
const money = (n) =&gt; String(n).replace(/\\B(?=(\\d{3})+(?!\\d))/g, &quot;,&quot;) + &quot; টাকা&quot;;
const chunks = DOCS.filter((d) =&gt; d.tenant === user.tenant &amp;&amp; d.vis === &quot;public&quot;).flatMap((d) =&gt; chunkDoc(d, 120));
const byId = new Map(chunks.map((c) =&gt; [c.id, c]));
const bm25 = buildBM25(chunks), vec = buildVector(chunks);

function findProduct(q) {
  const tq = trigrams(q);
  const mine = PRODUCTS.filter((p) =&gt; p.tenant === user.tenant);
  const scored = mine.map((p) =&gt; ({ p, s: cosMap(tq, trigrams(p.name)) })).sort((a, b) =&gt; b.s - a.s);
  return scored[0] &amp;&amp; scored[0].s &gt;= 0.35 ? scored[0].p : null;
}
function assistant(q) {
  const wantsPrice = /দাম|কত টাকা|মূল্য কত/.test(q), wantsStock = /স্টক|আছে কি|পাওয়া যাবে/.test(q) &amp;&amp; !wantsPrice;
  if (wantsPrice || wantsStock) {
    const p = findProduct(q);
    if (!p) return { kind: &quot;not_found&quot;, text: &quot;এই নামে কোনো পণ্য আমাদের তালিকায় খুঁজে পাইনি। নামটি আবার লিখবেন, বা একজন প্রতিনিধি জানাবেন।&quot;, source: null };
    if (wantsStock) return { kind: &quot;stock&quot;, text: p.stock &gt; 0 ? p.name + &quot; — স্টকে আছে (&quot; + p.stock + &quot;টি)।&quot; : p.name + &quot; — এখন স্টকে নেই।&quot;, source: &quot;record:&quot; + p.sku + &quot; | &quot; + p.updated };
    if (p.price == null) return { kind: &quot;price_unknown&quot;, text: p.name + &quot; — দাম এখন নিশ্চিত নয়; যাচাই করে জানাচ্ছি।&quot;, source: &quot;record:&quot; + p.sku + &quot; | &quot; + p.updated };
    return { kind: &quot;price&quot;, text: p.name + &quot; — দাম &quot; + money(p.price) + &quot;।&quot;, source: &quot;record:&quot; + p.sku + &quot; | &quot; + p.updated };
  }
  const cand = rrf([bm25(q, 6), vec(q, 6)], 60, 6).map((x) =&gt; byId.get(x.id));
  const tq = trigrams(q);
  let best = null;
  for (const c of cand) for (const s of sentences(c.text)) { const sc = cosMap(tq, trigrams(s)); if (!best || sc &gt; best.score) best = { s, c, score: sc }; }
  if (!best || best.score &lt; 0.3) return { kind: &quot;abstain&quot;, text: &quot;এই বিষয়ে আমাদের নথিতে তথ্য পাইনি; একজন প্রতিনিধি জানাবেন।&quot;, source: null };
  return { kind: &quot;doc&quot;, text: best.s, source: best.c.id + &quot; | &quot; + best.c.updated };
}

const SUITE = [
  { q: &quot;নীল সুতি শাড়ির দাম কত?&quot;, kind: &quot;price&quot;, fact: &quot;1,200 টাকা&quot;, src: &quot;record:SAREE-BLUE&quot; },
  { q: &quot;লন থ্রি-পিস স্টকে আছে?&quot;, kind: &quot;stock&quot;, fact: &quot;স্টকে নেই&quot;, src: &quot;record:LAWN-3PC&quot; },
  { q: &quot;লাল ওড়নার দাম কত?&quot;, kind: &quot;price_unknown&quot;, fact: &quot;নিশ্চিত নয়&quot;, src: &quot;record:SCARF-RED&quot; },
  { q: &quot;সিল্ক শাড়ির দাম কত?&quot;, kind: &quot;not_found&quot; },
  { q: &quot;ফেরত কত দিনের মধ্যে করা যায়?&quot;, kind: &quot;doc&quot;, fact: &quot;৭ দিনের মধ্যে&quot;, src: &quot;policy-return&quot; },
  { q: &quot;বিকাশে মূল্য পরিশোধ করা যায়?&quot;, kind: &quot;doc&quot;, fact: &quot;বিকাশ&quot;, src: &quot;faq-payment&quot; },
  { q: &quot;শাড়ির রং কি পাকা?&quot;, kind: &quot;doc&quot;, fact: &quot;রং পাকা&quot;, src: &quot;prod-saree-blue&quot; },
  { q: &quot;দোকান কয়টায় খোলে?&quot;, kind: &quot;abstain&quot; },
];
let pass = 0;
for (const t of SUITE) {
  const r = assistant(t.q);
  const okKind = r.kind === t.kind, okFact = !t.fact || r.text.includes(t.fact), okSrc = !t.src || (r.source || &quot;&quot;).startsWith(t.src);
  const ok = okKind &amp;&amp; okFact &amp;&amp; okSrc;
  if (ok) pass++;
  console.log(ok ? &quot;✓&quot; : &quot;✗&quot;, t.q, &quot;→&quot;, r.kind, &quot;|&quot;, r.text, r.source ? &quot;[&quot; + r.source + &quot;]&quot; : &quot;&quot;);
}
console.log(&quot;স্যুট:&quot;, pass + &quot;/&quot; + SUITE.length);
// নিরাপত্তা: উত্তরের প্রতিটি টাকার অঙ্ক কি রেকর্ড বা উদ্ধৃত নথিতে আছে?
const invented = SUITE.map((t) =&gt; assistant(t.q)).filter((r) =&gt; {
  const amounts = (r.text.match(/[0-9০-৯][0-9০-৯,]*\\s*টাকা/g) || []);
  return amounts.some((a) =&gt; { const n = a.replace(/[^0-9]/g, &quot;&quot;); const recOk = PRODUCTS.some((p) =&gt; p.tenant === user.tenant &amp;&amp; String(p.price) === n); const docOk = r.source &amp;&amp; byId.has(r.source.split(&quot; | &quot;)[0]) &amp;&amp; byId.get(r.source.split(&quot; | &quot;)[0]).text.includes(a); return !recOk &amp;&amp; !docOk; });
});
console.log(&quot;বানানো টাকার অঙ্ক:&quot;, invented.length, &quot;| অন্য দোকানের পণ্য উত্তরে:&quot;, SUITE.some((t) =&gt; (assistant(t.q).source || &quot;&quot;).indexOf(&quot;B-&quot;) &gt;= 0));</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>PRODUCTS</code>: দাম/স্টকের একমাত্র উৎস; <code>price: null</code> = অজানা, ০ নয়।</li><li><code>findProduct</code>: শুধু ব্যবহারকারীর tenant-এর রেকর্ড, এবং মিল সীমার ওপরে হলে।</li><li><code>assistant</code>: রেকর্ড-পথ ও নথি-পথ আলাদা; প্রতিটি উত্তরে <code>kind</code> ও <code>source</code>।</li><li><code>money</code>: regex দিয়ে হাজারের কমা (QuickJS-এ Intl নেই)।</li><li><code>invented</code>: উত্তরের প্রতিটি টাকার অঙ্ক রেকর্ড বা উদ্ধৃত নথিতে আছে কি—নিয়ম কোডে পরীক্ষিত।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>দাম ও স্টকের জন্য RAG নয়, সরাসরি রেকর্ড—কারণ এগুলো কাঠামোবদ্ধ, ঘন ঘন বদলায়, আর টেক্সট-খোঁজা ভুল পণ্যের দাম আনতে পারে। route-কে শব্দ-নিয়মে রাখা হয়েছে যাতে আচরণ সম্পূর্ণ দেখা যায়; বাস্তবে এটি অধ্যায় ১০-এর মতো একটি schema-যাচাই-করা শ্রেণিবিন্যাস বা tool call হতে পারে—কিন্তু রেকর্ড-অনুসন্ধান ও অনুমতি তখনও কোডেই থাকবে।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>দাম/স্টক রেকর্ড থেকে, টেক্সট থেকে নয়</li><li>অজানা = null, ০ নয়</li><li>না পেলে বলুন, বানাবেন না</li><li>tenant-ফিল্টার রেকর্ডেও</li><li>ধরন + তথ্য + উৎস একসাথে মাপুন</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>WooCommerce REST থেকে রেকর্ড আনা</li><li>বহু-পণ্য প্রশ্ন (“দুটোর দাম”)</li><li>ছবি দিয়ে পণ্য খোঁজা</li></ul></div></details>
<details class="wgba-disclose" open><summary>নিজে পরিবর্তন করে দেখুন</summary><div><p>SUITE-এ পাঁচটি কঠিন কেস যোগ করুন: বানান-ভুল নাম (“নিল সুতি শারি”), দুই পণ্য একসাথে, ইংরেজি নাম (“blue saree price”), দাম ও ফেরত একসাথে, এবং অন্য দোকানের পণ্যের নাম। কতগুলো পাস করে? প্রতিটি ব্যর্থতা কোন ধাপে?</p></div></details>
<section class="wgba-section" id="mistakes"><h2>সাধারণ ভুল</h2><ul><li>দাম/স্টক নথি-খোঁজা থেকে দেওয়া</li><li>পণ্য চেনা না গেলে কাছাকাছি পণ্যের দাম বলা</li><li>null দামকে ০ দেখানো</li><li>রেকর্ড-অনুসন্ধানে tenant-ফিল্টার ভুলে যাওয়া</li><li>শুধু “উত্তর এসেছে কি না” মাপা</li></ul></section>
<details class="wgba-disclose"><summary>সমাধান ও ব্যাখ্যা</summary><div><p>QuickJS-এ চালানো ফল: স্যুট ৮/৮, কোনো বানানো টাকার অঙ্ক নেই, অন্য দোকানের কোনো রেকর্ড উত্তরে আসেনি। “সিল্ক শাড়ি” shopB-র রেকর্ডের সাথে ০.৭১২ মেলে, কিন্তু tenant-ফিল্টারের কারণে সেটি প্রার্থীই নয়; shopA-র নীল সুতি শাড়ির সাথে মিল ০.২৮৯, সীমা ০.৩৫-এর নিচে, তাই “খুঁজে পাইনি”। সীমা ০.১ করলে এই প্রশ্নে নীল সুতি শাড়ির দাম চলে আসে—একটি ভুল পণ্যের সঠিক দাম, যা বানানো দামের মতোই ক্ষতিকর। পরিচিত দুর্বলতা (পরীক্ষায় পিন করা): “ঢাকার বাইরে ডেলিভারিতে কত টাকা লাগে?” route-এ “কত টাকা” দেখে দামের পথে যায় এবং not_found দেয়—ভুল তথ্য নয়, কিন্তু অসহায় উত্তর। স্যুট ৮/৮ হলেও সহকারী সম্পূর্ণ নয়; স্যুট যত বড় ও বৈচিত্র্যময়, সংখ্যাটি তত অর্থবহ।</p></div></details>
